 16	/** Dónde ve el contenedor el scratch del anfitrión. */
 17	export const LAB_SCRATCH_MOUNT = '/scratch'
 18	
 19	const MEMORY_SAMPLE_INTERVAL_MS = 1_000
 20	const MEASURED_STATE = 'measured'
 21	const BYTES_PER_MIB = 1024 ** 2
 22	/** Hilos de torch y de llama.cpp: el perfil por defecto (128) no alcanza a un convertidor con 4 CPUs. */
 23	const LAB_PIDS_LIMIT = 512
 24	
 25	export interface LabLimits {
 26	  readonly memoryBytes: number
 27	  readonly cpus: number
 28	}
 29	
 30	export interface LabOwner {
 31	  readonly id: string
 32	  readonly pid: number
 33	}
