 35	export interface LabStep {
 36	  /** Identidad del worker en la primitiva; su contenedor es `workerContainerName(workerId)`. */
 37	  readonly workerId: string
 38	  readonly command: readonly string[]
 39	}
 40	
 41	export interface LabStepResult extends JobOutput {
 42	  /** Pico de memoria del cgroup observado; ausente si ningún muestreo llegó a medir. */
 43	  readonly peakMemoryBytes?: number
 44	}
 45	
 46	/** Lee el pico de memoria del cgroup de un contenedor vivo; `undefined` si no pudo medirlo. */
 47	export type ContainerMemoryProbe = (containerName: string) => Promise<number | undefined>
 48	
 49	/**
 50	 * El laboratorio ejecuta cada paso por la primitiva de Podman
 51	 * (`runJobWithOutput`): crear, arrancar, esperar, leer salidas y retirar,
 52	 * con el dueño `lab` en sus etiquetas para que un barrido de huérfanos lo
 53	 * reconozca. El rootfs es escribible a propósito: el convertidor y sus
 54	 * dependencias escriben temporales fuera del scratch.
 55	 */
 56	export class QuantizationLab {
 57	  constructor(
 58	    private readonly podman: PodmanExecutor,
 59	    private readonly imageId: string,
 60	    private readonly scratchDir: string,
 61	    private readonly limits: LabLimits,
 62	    private readonly probe: ContainerMemoryProbe,
 63	    private readonly owner: LabOwner,
 64	  ) {}
 65	
 66	  async run(step: LabStep): Promise<LabStepResult> {
 67	    const containerName = workerContainerName(step.workerId)
 68	    const peak = new PeakTracker()
 69	    const sampler = setInterval(() => { void this.probe(containerName).then(value => peak.observe(value)) }, MEMORY_SAMPLE_INTERVAL_MS)
 70	    try {
 71	      const output = await runJobWithOutput(this.podman, this.specOf(step))
 72	      return { ...output, ...peak.asResult() }
 73	    } finally {
 74	      clearInterval(sampler)
 75	    }
 76	  }
 77	
 78	  private specOf(step: LabStep): WorkerContainerSpec {
 79	    return {
 80	      workerId: step.workerId,
 81	      image: this.imageId,
 82	      owner: { kind: 'lab', id: this.owner.id, pid: this.owner.pid },
 83	      resourceArgv: workerResourceLimitArgv(this.profile()),
 84	      command: step.command,
 85	    }
 86	  }
 87	
 88	  private profile(): WorkerResourceProfile {
 89	    return {
 90	      cpus: this.limits.cpus,
 91	      memoryMib: Math.floor(this.limits.memoryBytes / BYTES_PER_MIB),
 92	      pidsLimit: LAB_PIDS_LIMIT,
 93	      network: 'none',
 94	      readOnlyRootfs: false,
 95	      mounts: [{ source: this.scratchDir, destination: LAB_SCRATCH_MOUNT, mode: 'rw' }],
 96	    }
 97	  }
 98	}
 99	
100	class PeakTracker {
101	  private peak: number | undefined
102	
103	  observe(value: number | undefined): void {
104	    if (value !== undefined && (this.peak === undefined || value > this.peak)) this.peak = value
105	  }
106	
107	  asResult(): { peakMemoryBytes?: number } {
108	    return this.peak === undefined ? {} : { peakMemoryBytes: this.peak }
109	  }
110	}
111	
112	/** `container_measure read <name>` publica `measured <pico> <uso> <pids>`; otro estado no es una medida. */
113	export function parseContainerMeasure(stdout: string): number | undefined {
114	  const [state, peak] = stdout.trim().split(/\s+/)
115	  if (state !== MEASURED_STATE || peak === undefined) return undefined
116	  const value = Number(peak)
117	  return Number.isFinite(value) ? value : undefined
118	}
119	
120	export function containerMeasureProbe(containerMeasureBin: string): ContainerMemoryProbe {
121	  return async name => parseContainerMeasure((await runCommand(containerMeasureBin, ['read', name])).stdout)
122	}
