124	/** El ID inmutable de la imagen del laboratorio y su digest, para fijarla en la procedencia. */
125	export async function resolveLabImage(podman: PodmanExecutor, reference: string): Promise<{ id: string; digest: string }> {
126	  const result = await podman.run(['image', 'inspect', reference, '--format', '{{.Id}} {{.Digest}}'])
127	  const [id, digest] = result.stdout.trim().split(/\s+/)
128	  if (result.exitCode !== 0 || !id || !digest) throw new Error(`la imagen del laboratorio ${reference} no está: ${result.stderr.trim()}`)
129	  return { id, digest }
130	}

